# Analyze each transformation
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find what changed
        if len(inp) <= len(outp):
            # Look for substring replacements
            for j in range(len(inp)):
                if j + 1 <= len(inp):
                    substr = inp[j:j+1]
                    if substr in outp:
                        print(f"  Found substring '{substr}' in output")
        print(f"  Length change: {len(inp)} -> {len(outp)}")
    else:
        print("  No change needed")
    print()

